    vector<pair<int,int>> intervals(N);
    for (auto& [l, r] : intervals) cin >> l >> r;

    // Compute x: greedy interval cover
    vector<pair<int,int>> sorted_iv = intervals;
    sort(sorted_iv.begin(), sorted_iv.end());

    int x = 0, covered = 0, i = 0;
    while (covered < L) {
        int best = covered;
        while (i < N && sorted_iv[i].first <= covered) {
            best = max(best, sorted_iv[i].second);
            i++;
        }
        if (best == covered) { x = -1; break; } // can't cover
        covered = best;
        x++;
    }

    // Compute y: sweep line for min coverage in [0, L)
    vector<pair<int,int>> events;
    for (auto [l, r] : intervals) {
        int cl = max(l, 0), cr = min(r, L);
        if (cl < cr) {
            events.push_back({cl, 1});
            events.push_back({cr, -1});
        }
    }
    sort(events.begin(), events.end());

    int min_cov = INT_MAX, cur_cov = 0, prev = 0;
    // Need to check coverage at each point - use coordinate compression
    // Actually sweep over events
    // Check coverage in intervals between events within [0, L)
    vector<int> coords = {0, L};
    for (auto [p, _] : events) coords.push_back(p);
    sort(coords.begin(), coords.end());
    coords.erase(unique(coords.begin(), coords.end()), coords.end());

    // For each segment [coords[i], coords[i+1]) within [0,L), find coverage
    map<int, int> delta;
    for (auto [l, r] : intervals) {
        int cl = max(l, 0), cr = min(r, L);
        if (cl < cr) { delta[cl]++; delta[cr]--; }
    }

    cur_cov = 0; int pos = 0;
    for (auto& [p, d] : delta) {
        if (p > pos && pos < L) min_cov = min(min_cov, cur_cov);
        cur_cov += d;
    }
    if (pos < L) min_cov = min(min_cov, cur_cov); // after last event

    int y = N - min_cov + 1;
    cout << x << " " << y << endl;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    long long L;
    cin >> N >> L;

    vector<pair<long long,long long>> segs(N);
    for (int i = 0; i < N; ++i) {
        cin >> segs[i].first >> segs[i].second;
    }

    // x: minimum number of intervals needed so that there exists a choice
    // covering [0, L). Greedy minimum interval cover.
    vector<pair<long long,long long>> a = segs;
    sort(a.begin(), a.end());

    const int INF = 1e9;
    int x = INF;
    long long cur = 0;
    int i = 0, used = 0;
    bool ok = true;

    while (cur < L) {
        long long best = cur;
        while (i < N && a[i].first <= cur) {
            best = max(best, a[i].second);
            ++i;
        }
        if (best == cur) {
            ok = false;
            break;
        }
        cur = best;
        ++used;
    }
    if (ok) x = used;

    // y: minimum y such that every subset of size y covers [0, L).
    // Equivalent: let m be the maximum number of intervals one can choose
    // while still NOT covering [0, L). Then y = m + 1.
    //
    // A subset fails to cover iff there exists a point t in [0, L) uncovered by all
    // chosen intervals. Thus the maximum such subset size equals:
    // max over t in [0, L) of (# intervals that do NOT contain t).
    // So if c(t) is number of intervals containing t, then
    // m = N - min_t c(t), and y = N - min_t c(t) + 1.
    //
    // We compute minimum coverage count on [0, L) by sweep line.
    vector<pair<long long,int>> events;
    events.reserve(2 * N);
    for (auto &p : segs) {
        long long l = p.first, r = p.second;
        long long s = max(0LL, l);
        long long e = min(L, r);
        if (s < e) {
            events.push_back({s, +1});
            events.push_back({e, -1});
        }
    }
    sort(events.begin(), events.end());

    int curCov = 0;
    int minCov = INT_MAX;
    long long prev = 0;
    int idx = 0, M = (int)events.size();

    while (idx < M) {
        long long pos = events[idx].first;
        if (prev < pos && prev < L) {
            long long right = min(pos, L);
            if (prev < right) minCov = min(minCov, curCov);
        }
        while (idx < M && events[idx].first == pos) {
            curCov += events[idx].second;
            ++idx;
        }
        prev = pos;
    }
    if (prev < L) minCov = min(minCov, curCov);
    if (minCov == INT_MAX) minCov = 0; // no active segment anywhere in [0,L)

    int y = N - minCov + 1;

    // If covering [0,L) is impossible at all, x has no valid finite value.
    // In most problem settings this case does not occur. We print -1 for x.
    if (x == INF) x = -1;

    cout << x << " " << y << '\n';
    return 0;
}

