typedef struct {
    int l, r;
} Interval;

int cmp(const void *a, const void *b) {
    Interval *ia = (Interval*)a;
    Interval *ib = (Interval*)b;
    if (ia->l != ib->l) return ia->l - ib->l;
    return ia->r - ib->r;
}

int main() {
    int N, L;
    scanf("%d %d", &N, &L);
    Interval *intervals = malloc(N * sizeof(Interval));
    for (int i = 0; i < N; i++) {
        scanf("%d %d", &intervals[i].l, &intervals[i].r);
    }
    qsort(intervals, N, sizeof(Interval), cmp);

    // Part 1: minimum x to cover [0, L)
    int x = 0;
    int covered = 0;
    int i = 0;
    int ok = 1;
    while (covered < L) {
        int best = covered;
        while (i < N && intervals[i].l <= covered) {
            if (intervals[i].r > best)
                best = intervals[i].r;
            i++;
        }
        if (best == covered) {
            ok = 0;
            break;
        }
        covered = best;
        x++;
    }
    if (!ok) x = -1; // impossible case, but problem likely guarantees coverage

    // Part 2: minimum y such that ANY y intervals cover [0, L)
    // Find maximum removable intervals
    int removable = 0;
    covered = 0;
    i = 0;
    int current_farthest = 0;
    int count_in_use = 0;
    while (covered < L) {
        int best = covered;
        int cnt = 0;
        while (i < N && intervals[i].l <= covered) {
            if (intervals[i].r > best) {
                best = intervals[i].r;
            }
            cnt++;
            i++;
        }
        // We need at least one interval to extend coverage
        // The others in this batch could be removed (except the one we pick)
        if (best == covered) break;
        removable += (cnt - 1); // all but the chosen one are removable
        covered = best;
        count_in_use++;
    }
    // total intervals needed = count_in_use
    // removable = N - count_in_use
    removable = N - count_in_use;
    int y = N - removable; // = count_in_use
    // Actually y is the smallest number such that any y intervals cover:
    // That is N - max_removable.
    // max_removable = removable computed above
    y = N - removable;

    printf("%d %d\n", x, y);
    free(intervals);
    return 0;
}

