typedef long long ll;

typedef struct {
    ll l, r;
} Interval;

int cmp_interval(const void *a, const void *b) {
    const Interval *x = (const Interval *)a;
    const Interval *y = (const Interval *)b;
    if (x->l < y->l) return -1;
    if (x->l > y->l) return 1;
    if (x->r < y->r) return -1;
    if (x->r > y->r) return 1;
    return 0;
}

int main(void) {
    int N;
    ll L;
    if (scanf("%d %lld", &N, &L) != 2) return 0;

    Interval *a = (Interval *)malloc(sizeof(Interval) * N);
    for (int i = 0; i < N; ++i) {
        scanf("%lld %lld", &a[i].l, &a[i].r);
    }

    qsort(a, N, sizeof(Interval), cmp_interval);

    /* x: minimum number of intervals whose union covers [0, L) */
    int x = 0;
    ll covered = 0;
    int i = 0;
    int possible = 1;

    while (covered < L) {
        ll best = covered;
        while (i < N && a[i].l <= covered) {
            if (a[i].r > best) best = a[i].r;
            i++;
        }
        if (best == covered) {
            possible = 0;
            break;
        }
        covered = best;
        x++;
    }

    if (!possible) {
        /* If covering [0,L) is impossible at all, no valid x/y exist.
           The statement typically guarantees existence, but print -1 -1 otherwise. */
        printf("-1 -1\n");
        free(a);
        return 0;
    }

    /* y: minimum y such that every choice of y intervals covers [0, L)
       Equivalent to:
       let m = maximum number of intervals that can be chosen while STILL NOT covering [0, L)
       then y = m + 1

       A set fails to cover [0,L) iff there exists a point/gap in [0,L) uncovered by all chosen intervals.
       So m = max over t in [0,L) of (# intervals that do NOT cover t).
       Hence y = N - max_t(# intervals not covering t) + 1
               = N - (N - min_t(# intervals covering t)) + 1
               = min_t(# intervals covering t) + 1

       Also, a set can fail by missing 0 or missing some suffix before L; these are included by points in [0,L).
       Thus y = minimum coverage multiplicity over points in [0,L), plus 1.
    */

    typedef struct {
        ll pos;
        int delta;
    } Event;

    Event *ev = (Event *)malloc(sizeof(Event) * 2 * N);
    int m = 0;

    for (int j = 0; j < N; ++j) {
        ll l = a[j].l, r = a[j].r;
        if (r <= 0 || l >= L) continue;
        if (l < 0) l = 0;
        if (r > L) r = L;
        if (l < r) {
            ev[m++] = (Event){l, +1};
            ev[m++] = (Event){r, -1};
        }
    }

    int cmp_event(const void *p, const void *q) {
        const Event *a = (const Event *)p;
        const Event *b = (const Event *)q;
        if (a->pos < b->pos) return -1;
        if (a->pos > b->pos) return 1;
        return b->delta - a->delta; /* starts before ends at same pos */
    }

    qsort(ev, m, sizeof(Event), cmp_event);

    int cur = 0;
    int mincov = 1 << 30;
    ll prev = 0;
    int idx = 0;

    while (idx < m) {
        ll p = ev[idx].pos;

        if (prev < p) {
            if (cur < mincov) mincov = cur;
        }

        while (idx < m && ev[idx].pos == p && ev[idx].delta == +1) {
            cur += 1;
            idx++;
        }
        while (idx < m && ev[idx].pos == p && ev[idx].delta == -1) {
            cur -= 1;
            idx++;
        }

        prev = p;
    }

    if (prev < L) {
        if (cur < mincov) mincov = cur;
    }

    int y = mincov + 1;

    printf("%d %d\n", x, y);

    free(ev);
    free(a);
    return 0;
}

