import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int L = sc.nextInt();
        int[][] intervals = new int[N][2];
        for (int i = 0; i < N; i++) {
            intervals[i][0] = sc.nextInt();
            intervals[i][1] = sc.nextInt();
        }

        // Sort intervals by start
        Arrays.sort(intervals, (a, b) -> Integer.compare(a[0], b[0]));

        // 1. Minimum number of intervals to cover [0, L)
        int minCover = 0;
        int curEnd = 0;
        int i = 0;
        while (curEnd < L && i < N) {
            int bestEnd = curEnd;
            while (i < N && intervals[i][0] <= curEnd) {
                bestEnd = Math.max(bestEnd, intervals[i][1]);
                i++;
            }
            if (bestEnd == curEnd) {
                minCover = -1; // impossible
                break;
            }
            curEnd = bestEnd;
            minCover++;
        }
        if (curEnd < L) minCover = -1;

        // 2. Minimum y such that all combinations of y intervals cover [0, L)
        // This is N - (size of largest subset that leaves a gap)
        // Equivalent: find the maximum number of intervals we can remove while still covering.
        // We can think: consider coverage without each interval, find largest uncovered gap.

        // Build sorted list of endpoints for coverage check
        int maxRemovable = 0;
        // For each interval, simulate removal and check coverage
        for (int skip = 0; skip < N; skip++) {
            int end = 0;
            int cnt = 0;
            int j = 0;
            while (end < L && j < N) {
                if (j == skip) { j++; continue; }
                int bestEnd = end;
                while (j < N && intervals[j][0] <= end) {
                    if (j != skip)
                        bestEnd = Math.max(bestEnd, intervals[j][1]);
                    j++;
                }
                if (bestEnd == end) break;
                end = bestEnd;
                cnt++;
            }
            if (end >= L) {
                maxRemovable = Math.max(maxRemovable, N - cnt);
            }
        }

        int y = N - maxRemovable;
        if (minCover == -1) y = -1;

        System.out.println(minCover + " " + y);
    }
}

