public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        int L = Integer.parseInt(st.nextToken());

        int[][] intervals = new int[N][2];
        for (int i = 0; i < N; i++) {
            st = new StringTokenizer(br.readLine());
            intervals[i][0] = Integer.parseInt(st.nextToken());
            intervals[i][1] = Integer.parseInt(st.nextToken());
        }

        // Find x: minimum intervals to cover [0, L)
        Arrays.sort(intervals, (a, b) -> a[0] != b[0] ? a[0] - b[0] : a[1] - b[1]);
        int x = 0, pos = 0, i = 0;
        while (pos < L) {
            int maxR = pos;
            while (i < N && intervals[i][0] <= pos) {
                maxR = Math.max(maxR, intervals[i][1]);
                i++;
            }
            if (maxR <= pos) { x = -1; break; } // can't cover
            pos = maxR;
            x++;
        }

        // Find y: minimum y such that all size-y subsets cover [0,L)
        // y = N - m + 1 where m = min coverage count over [0,L)
        TreeMap<Integer, Integer> events = new TreeMap<>();
        for (int[] interval : intervals) {
            if (interval[0] < L && interval[1] > 0) {
                int l = Math.max(interval[0], 0), r = Math.min(interval[1], L);
                events.merge(l, 1, Integer::sum);
                events.merge(r, -1, Integer::sum);
            }
        }
        int minCov = Integer.MAX_VALUE, cur = 0, prev = 0;
        for (Map.Entry<Integer, Integer> e : events.entrySet()) {
            if (e.getKey() > prev && prev < L) minCov = Math.min(minCov, cur);
            cur += e.getValue();
            prev = e.getKey();
        }
        if (prev < L) minCov = Math.min(minCov, cur);

        int y = (minCov == Integer.MAX_VALUE) ? N + 1 : N - minCov + 1;

        System.out.println(x + " " + y);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Interval {
        long l, r;
        Interval(long l, long r) {
            this.l = l;
            this.r = r;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int N;
        long L;
        try {
            N = fs.nextInt();
            L = fs.nextLong();
        } catch (Exception e) {
            return;
        }

        Interval[] a = new Interval[N];
        for (int i = 0; i < N; i++) {
            long l = fs.nextLong();
            long r = fs.nextLong();
            a[i] = new Interval(l, r);
        }

        // x: minimum number of intervals such that there exists a choice of x intervals covering [0, L)
        // Greedy minimum interval cover.
        Arrays.sort(a, (p, q) -> {
            if (p.l != q.l) return Long.compare(p.l, q.l);
            return Long.compare(q.r, p.r);
        });

        long covered = 0;
        int i = 0;
        int x = 0;
        boolean possible = true;

        while (covered < L) {
            long best = covered;
            while (i < N && a[i].l <= covered) {
                if (a[i].r > best) best = a[i].r;
                i++;
            }
            if (best == covered) {
                possible = false;
                break;
            }
            covered = best;
            x++;
        }

        // y: minimum integer such that every choice of y intervals covers [0, L)
        // Equivalent: any subset of size y covers [0, L)
        // <=> there is no subset of size N - y that can be removed while still leaving some point uncovered
        // <=> let m = maximum number of intervals that can all miss a common point in [0, L)
        // then y = N - m + 1
        //
        // For half-open intervals [l, r), an interval misses point p iff !(l <= p < r).
        // So m = max over p in [0, L) of (# intervals not covering p) = N - minCoverage.
        // Hence y = minCoverage + 1.
        //
        // If minCoverage = 0, then y = 1 (indeed every 1-subset covers iff each interval covers all points, impossible unless L=0).
        // More directly, formula is valid.

        ArrayList<long[]> events = new ArrayList<>();
        for (Interval in : a) {
            long l = Math.max(0, in.l);
            long r = Math.min(L, in.r);
            if (l < r) {
                events.add(new long[]{l, +1});
                events.add(new long[]{r, -1});
            }
        }

        events.sort((u, v) -> {
            if (u[0] != v[0]) return Long.compare(u[0], v[0]);
            return Long.compare(u[1], v[1]); // -1 before +1 at same point for half-open handling on segments
        });

        long minCov;
        if (L == 0) {
            minCov = 0;
        } else {
            minCov = Long.MAX_VALUE;
            long cur = 0;
            long prev = 0;
            int idx = 0;

            while (idx < events.size()) {
                long pos = events.get(idx)[0];
                if (prev < pos) {
                    // coverage on [prev, pos) is cur
                    minCov = Math.min(minCov, cur);
                }
                while (idx < events.size() && events.get(idx)[0] == pos) {
                    cur += events.get(idx)[1];
                    idx++;
                }
                prev = pos;
            }
            if (prev < L) {
                minCov = Math.min(minCov, cur);
            }
            if (minCov == Long.MAX_VALUE) minCov = 0;
        }

        long y = minCov + 1;

        // If covering [0, L) is impossible even with all intervals, x has no valid value.
        // Most problem settings guarantee existence; if not, output -1 for x.
        if (!possible) x = -1;

        System.out.println(x + " " + y);
    }
}
